<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { Apple, ArrowRight, Bell, Beef, Broccoli, Carrot, Check, ChevronDown, ChevronLeft, ChevronRight, Clock3, CookingPot, CreditCard, CupSoda, Drumstick, Fish, Ham, Heart, Leaf, LeafyGreen, LoaderCircle, MapPin, Minus, PackageCheck, Plus, RotateCw, Salad, Search, ShieldCheck, ShoppingBag, ShoppingBasket, Sparkles, Sprout, Star, Truck, Wheat, X } from '@lucide/vue'
import AdminDashboard from './components/AdminDashboardFull.vue'
import CustomerAuthPage from './components/CustomerAuthPage.vue'
import Sheet from './components/Sheet.vue'
import { useMarket } from './store.js'
import { canPurchase, filterProducts, money, orderLabels } from './domain.js'
import { productImageFor } from './productImages.js'

const market = useMarket(), s = market.state
const view = ref(location.hash.startsWith('#merchant') ? 'merchant' : 'market'), search = ref(''), sort = ref('featured'), activeSection = ref('sale'), showCart = ref(false), showCheckout = ref(false), showAddress = ref(false), showAccount = ref(false), showActivityDetail = ref(false), showSetmealDetail = ref(false), showProductDetail = ref(false), addingActivityToCart = ref(false), selectedSetmeal = ref(null), selectedProduct = ref(null), selectedFlavors = reactive({}), selectedActivity = ref(null), selectedAddress = ref(null), activeOrder = ref(null), addressTarget = ref(null), addressReturn = ref(false), addressForm = reactive({ id: null, consignee: '', phone: '', detail: '', label: '家' }), deliveryEstimate = ref('约 30 分钟送达'), checkoutRemark = ref(''), processing = ref(false)
const harvestDay = new Intl.DateTimeFormat('en-US', { weekday: 'long', timeZone: 'Asia/Shanghai' }).format(new Date()).toUpperCase()
const filteredProducts = computed(() => filterProducts(s.products, null, search.value, sort.value))
const filteredSetmeals = computed(() => filterProducts(s.setmeals, null, search.value, sort.value))
const productsForCategory = categoryId => filterProducts(s.products, Number(categoryId), search.value, sort.value)
const visibleCategories = computed(() => s.categories.filter(category => productsForCategory(category.id).length))
const categorySectionId = category => `category-${category.id}`
const categoryIcons = [
  [/猪/, Ham], [/牛羊|牛肉/, Beef], [/禽|鸡鸭/, Drumstick], [/水产|鱼|海鲜/, Fish],
  [/叶菜/, LeafyGreen], [/花菜|西兰花/, Broccoli], [/根茎/, Carrot], [/瓜果蔬菜/, Salad],
  [/菌菇/, Sprout], [/蛋品|豆制品|主食/, Wheat], [/水果/, Apple], [/调味|配料/, CookingPot],
  [/饮料|酒水/, CupSoda], [/套餐|组合/, ShoppingBasket],
]
function categoryIcon(category) { return categoryIcons.find(([pattern]) => pattern.test(String(category?.name || '')))?.[1] || Leaf }
const scrollSectionIds = computed(() => ['sale', ...s.categories.map(categorySectionId), ...(s.setmeals.length ? ['setmeals'] : [])])
const totalItems = computed(() => s.cart.reduce((sum, p) => sum + p.number, 0))
const openActivities = computed(() => s.activities.filter(a => canPurchase(a)))
const orderFilter = ref('all')
const latestOrders = computed(() => [...s.orders].filter(order => orderFilter.value === 'all' || Number(order.status) === Number(orderFilter.value)).sort((a, b) => String(b.orderTime || '').localeCompare(String(a.orderTime || ''))))
const salePulse = ref(false)
let salePulseTimer
const loggedIn = computed(() => Boolean(s.userToken))
const needsAuthentication = computed(() => view.value === 'merchant' ? !s.adminToken : !s.userToken)
const addressName = computed(() => selectedAddress.value?.consignee || (s.mode === 'demo' ? '晓雨' : '选择收货地址'))
async function go(next) { view.value = next; location.hash = next === 'merchant' ? '#merchant' : '#market'; scrollTo({ top: 0, behavior: 'smooth' }); if (next === 'merchant') market.refreshAdmin(); else if (s.mode !== 'live') await market.setMode('live') }
function onHash() { view.value = location.hash.startsWith('#merchant') ? 'merchant' : 'market'; if (view.value === 'merchant') market.refreshAdmin(); else if (s.mode !== 'live') market.setMode('live') }
function signedOutCustomer() { sessionStorage.removeItem('fresh-user-token'); sessionStorage.removeItem('fresh-user-auth'); sessionStorage.removeItem('fresh-user-name'); s.userToken = ''; s.userName = ''; market.setMode('live').catch(() => {}) }
function onAuthenticated(role) { go(role === 'merchant' ? 'merchant' : 'market') }
function imageError(event, name = event.currentTarget?.alt) { event.currentTarget.onerror = null; event.currentTarget.src = productImageFor(name) }
function updateActiveSection() {
  if (view.value !== 'market') return
  const marker = window.innerWidth <= 760 ? 126 : 96
  let current = 'sale'
  for (const id of scrollSectionIds.value) {
    if (id === 'sale') continue
    const target = document.getElementById(id)
    if (!target) continue
    if (target.getBoundingClientRect().top <= marker) current = id
    else break
  }
  activeSection.value = current
}
let scrollFrame = 0
function onPageScroll() {
  if (scrollFrame) return
  scrollFrame = window.requestAnimationFrame(() => { scrollFrame = 0; updateActiveSection() })
}
function scrollToSection(id) {
  activeSection.value = id
  const target = document.getElementById(id)
  if (!target) return
  if (id === 'sale') {
    salePulse.value = true
    window.clearTimeout(salePulseTimer)
    salePulseTimer = window.setTimeout(() => { salePulse.value = false }, 1400)
  }
  const offset = window.matchMedia('(max-width: 760px)').matches ? 114 : 82
  const top = window.scrollY + target.getBoundingClientRect().top - offset
  window.scrollTo({ top: Math.max(0, top), behavior: 'smooth' })
}
function browseCategory(category) { search.value = ''; nextTick(() => scrollToSection(categorySectionId(category))) }
function browseSetmeals() { search.value = ''; nextTick(() => scrollToSection('setmeals')) }
watch(search, () => nextTick(updateActiveSection))
function isFavorite(id) { return s.favorites.includes(id) }
function count(product, flavor = '') { return s.cart.filter(p => (product.kind === 'setmeal' ? Number(p.setmealId) === Number(product.id) : Number(p.dishId) === Number(product.id)) && (flavor ? (p.dishFlavor || '') === flavor : true)).reduce((sum, row) => sum + Number(row.number || 0), 0) }
function quantity(item) { return s.cart.find(p => p.id === item.id)?.number || 0 }
function flavorOptions(flavor) { return String(flavor.value || '').split(/[,，/、]/).map(value => value.trim()).filter(Boolean) }
function openProductDetail(product) { selectedProduct.value = product; for (const key of Object.keys(selectedFlavors)) delete selectedFlavors[key]; for (const flavor of product.flavors || []) selectedFlavors[flavor.name] = flavorOptions(flavor)[0] || ''; showProductDetail.value = true }
async function add(product, flavor = '', selected = false) { if (!loggedIn.value) return; if (!selected && !product.setmealId && product.kind !== 'setmeal' && product.flavors?.length) { openProductDetail(product); return } await market.addCart(product, flavor) }
async function addSelectedFlavor() { if (!selectedProduct.value) return; const flavor = Object.entries(selectedFlavors).map(([name, value]) => `${name}:${value}`).join(' / '); await add(selectedProduct.value, flavor, true); showProductDetail.value = false }
async function minus(item) { await market.subtract(item) }
function addressFormOpen(activity = null, address = null, fromAccount = false) { addressTarget.value = activity; addressReturn.value = fromAccount; Object.assign(addressForm, address ? { id: address.id, consignee: address.consignee || '', phone: address.phone || '', detail: address.detail || '', label: address.label || '家' } : { id: null, consignee: '', phone: '', detail: '', label: '家' }); showCart.value = false; showCheckout.value = false; showActivityDetail.value = false; showAddress.value = true }
async function editAddress(address) { try { addressFormOpen(null, await market.addressDetail(address), true) } catch { } }
async function resolveDefaultAddress() { try { return await market.defaultAddress() || s.addresses.find(a => Number(a.isDefault) === 1) || s.addresses[0] || null } catch (error) { market.say(error.message); return s.addresses.find(a => Number(a.isDefault) === 1) || s.addresses[0] || null } }
async function chooseCheckout() { if (!s.cart.length) { market.say('购物袋还是空的，先挑些今日鲜货吧'); showCart.value = false; return } if (!s.addresses.length) { addressFormOpen(); return } selectedAddress.value = await resolveDefaultAddress(); showCart.value = false; showCheckout.value = true }
async function saveAddress() { try { const value = { ...addressForm, consignee: addressForm.consignee.trim(), phone: addressForm.phone.trim(), detail: addressForm.detail.trim(), provinceCode: '110000', provinceName: '北京市', cityCode: '110100', cityName: '北京市', districtCode: '110108', districtName: '海淀区' }; await market.address(value); if (!value.id && s.addresses.length === 1 && !s.addresses[0].isDefault) await market.setDefaultAddress(s.addresses[0]); selectedAddress.value = s.addresses.find(a => a.isDefault === 1) || s.addresses.at(-1); showAddress.value = false; if (addressReturn.value) { showAccount.value = true } else if (addressTarget.value) { selectedActivity.value = addressTarget.value; showActivityDetail.value = true } else if (s.cart.length) showCheckout.value = true; addressTarget.value = null; addressReturn.value = false } catch { } }
async function placeOrder() { if (processing.value) return; if (!selectedAddress.value) { addressFormOpen(); return } processing.value = true; try { const result = await market.submit(selectedAddress.value.id, checkoutRemark.value); showCheckout.value = false; checkoutRemark.value = ''; showActivityDetail.value = false; if (s.mode === 'demo') { await market.orderAction(s.orders.find(o => o.id === result.id) || { ...result, id: result.id }, 'pay'); await market.refreshUser(); activeOrder.value = s.orders.find(o => o.id === result.id) || result } else { activeOrder.value = await market.orderDetail(result, false); market.say('订单已提交，可在订单详情中完成模拟支付。') } showAccount.value = true } catch { } finally { processing.value = false } }
async function startPurchase(activity) { if (!loggedIn.value) return; try { selectedActivity.value = await market.activityDetail(activity); if (!s.addresses.length) { addressFormOpen(selectedActivity.value); return } selectedAddress.value = await resolveDefaultAddress(); showActivityDetail.value = true } catch { } }
async function addActivityToCart(activity) {
  if (addingActivityToCart.value) return
  if (!activity?.dishId) { market.say('活动商品信息暂不可用，请刷新后重试'); return }
  const product = s.products.find(item => Number(item.id) === Number(activity.dishId))
  if (!product) { market.say('这件商品暂时无法加入购物袋，请刷新后重试'); return }
  addingActivityToCart.value = true
  try {
    await market.addCart(product)
    showActivityDetail.value = false
    showCart.value = true
  } finally { addingActivityToCart.value = false }
}
async function openSetmeal(meal) { try { selectedSetmeal.value = await market.setmealDetail(meal); showSetmealDetail.value = true } catch { } }
async function confirmPurchase() { if (processing.value || !selectedActivity.value) return; processing.value = true; try { const activity = selectedActivity.value, requestId = `xj-${activity.id}-${crypto.randomUUID()}`; let result = await market.purchase(activity, selectedAddress.value?.id, requestId); if (result.status === 0 || (result.status === 1 && !result.orderId)) { for (let attempt = 0; attempt < 22 && (result.status === 0 || (result.status === 1 && !result.orderId)); attempt++) { await new Promise(resolve => setTimeout(resolve, 1200)); result = await market.purchaseResult(requestId) || result; if (result.status === 2) break } }; if (result.status === 0) throw new Error('抢购请求已进入队列，可稍后在订单中查看'); if (result.status === 2) throw new Error(result.message || '没有抢到，再看看别的鲜品'); await market.refreshUser(); const order = s.orders.find(o => Number(o.id) === Number(result.orderId)) || { id: result.orderId, orderNumber: result.orderNumber, amount: activity.salePrice, activityId: activity.id, status: 1 }; selectedActivity.value = null; showActivityDetail.value = false; activeOrder.value = order; showAccount.value = true; market.say(result.message || '抢购成功，请完成付款') } catch { } finally { processing.value = false } }
async function orderAction(order, action) { if (processing.value) return; if (action === 'cancel' && !window.confirm('确定取消这笔订单吗？')) return; processing.value = true; try { const result = await market.orderAction(order, action); await market.refreshUser(); activeOrder.value = action === 'wechatPay' ? (s.orders.find(o => o.id === order.id) || order) : (s.orders.find(o => o.id === order.id) || null); if (action === 'wechatPay') await invokeWechatPayment(result); if (action === 'repeat') { activeOrder.value = null; showAccount.value = false; showCart.value = true } if (action === 'reminder') market.say('已提醒商家尽快处理') } catch { } finally { processing.value = false } }
function clearCart() { if (window.confirm('清空购物袋中的所有商品？')) market.clearCart() }
async function payOrder(order) { await orderAction(order, 'pay') }
async function repeatOrder(order) { if (!loggedIn.value) return; try { await market.repeatOrder(order); activeOrder.value = null; showAccount.value = false; showCart.value = true } catch { } }
async function setDefaultAddress(address) { try { await market.setDefaultAddress(address); selectedAddress.value = s.addresses.find(item => Number(item.id) === Number(address.id)) || address } catch { } }
async function removeAddress(address) { if (!window.confirm(`删除收货地址“${address.detail}”？`)) return; try { await market.deleteAddress(address); if (Number(selectedAddress.value?.id) === Number(address.id)) selectedAddress.value = s.addresses.find(item => item.isDefault === 1) || s.addresses[0] || null } catch { } }
async function invokeWechatPayment(payment) { const bridge = window.WeixinJSBridge; if (!bridge?.invoke) { market.say('已生成微信预支付信息；请在微信环境中打开后完成支付。'); return } const args = { appId: payment?.appid || payment?.appId, timeStamp: String(payment?.timeStamp || ''), nonceStr: payment?.nonceStr || '', package: payment?.packageStr || payment?.package || '', signType: payment?.signType || 'RSA', paySign: payment?.paySign || '' }; await new Promise((resolve, reject) => bridge.invoke('getBrandWCPayRequest', args, result => result?.err_msg === 'get_brand_wcpay_request:ok' ? resolve() : result?.err_msg === 'get_brand_wcpay_request:cancel' ? reject(new Error('已取消微信支付')) : reject(new Error('微信支付未完成')))); await market.refreshUser(); market.say('支付结果正在确认，请稍后刷新订单') }
async function addToFavorites(product) { const was = isFavorite(product.id); market.favorite(product.id); if (!was) await add(product) }
async function openOrder(order) { activeOrder.value = order; showAccount.value = true; try { activeOrder.value = await market.orderDetail(order, false) } catch { } }
function placeLabel(id) { return s.categories.find(c => Number(c.id) === Number(id))?.name || '鲜品直采' }
function handleKeys(event) { if (event.key === '/' && !['INPUT', 'TEXTAREA'].includes(document.activeElement?.tagName)) { event.preventDefault(); document.querySelector('.search-field__input')?.focus() } }
onMounted(async () => { window.addEventListener('hashchange', onHash); window.addEventListener('keydown', handleKeys); window.addEventListener('scroll', onPageScroll, { passive: true }); if (view.value === 'market' && s.mode !== 'live') await market.setMode('live'); else await market.refreshShop(); if (view.value === 'merchant') await market.refreshAdmin(); if (s.adminToken && s.mode === 'live') market.refreshAdmin().then(() => market.connectSocket?.()).catch(() => {}); await nextTick(); updateActiveSection() })
onBeforeUnmount(() => { window.removeEventListener('hashchange', onHash); window.removeEventListener('keydown', handleKeys); window.removeEventListener('scroll', onPageScroll); if (scrollFrame) window.cancelAnimationFrame(scrollFrame); window.clearTimeout(salePulseTimer); market.dispose() })
</script>

<template>
  <div v-if="view === 'merchant' && s.adminToken" class="merchant-experience"><AdminDashboard :on-back="() => go('market')" :on-login="() => go('merchant')" /></div>
  <CustomerAuthPage v-else-if="needsAuthentication" :initial-role="view === 'merchant' ? 'merchant' : 'customer'" @authenticated="onAuthenticated" />
  <div v-else class="shop-layout">
    <aside class="store-rail"><a href="#market" class="brand" @click.prevent="go('market')"><span class="brand__mark"><Leaf :size="21" /></span><span class="brand__text"><strong>鲜集<span class="brand__roman">FRESH MARKET</span></strong><small>好鲜，不必等</small></span></a><div class="store-rail__rule"/><span class="aside-label">去逛逛 <i>EXPLORE</i></span><nav class="main-nav" aria-label="商店导航"><button :class="['main-nav__item', { 'is-active': activeSection === 'sale' }]" @click="scrollToSection('sale')"><span class="main-nav__icon"><Clock3 :size="18" /></span>限时特卖</button><button v-for="category in s.categories" :key="category.id" :class="['main-nav__item', { 'is-active': activeSection === categorySectionId(category) }]" @click="browseCategory(category)"><span class="main-nav__icon"><component :is="categoryIcon(category)" :size="17" :stroke-width="1.8" /></span>{{ category.name }}</button><button v-if="s.setmeals.length" :class="['main-nav__item', { 'is-active': activeSection === 'setmeals' }]" @click="browseSetmeals"><span class="main-nav__icon"><ShoppingBasket :size="17" :stroke-width="1.8" /></span>鲜食套餐</button></nav><button class="rail-account" @click="showAccount = true"><span class="avatar">{{ s.userName ? s.userName.slice(0, 1) : '客' }}</span><span><b>{{ s.userName || '鲜集访客' }}</b><small>{{ s.mode === 'demo' ? '体验会员' : s.userToken ? '已连接用户' : '欢迎来逛逛' }}</small></span><ChevronRight :size="16" /></button></aside>
    <main class="shop-main"><header class="shop-header"><div class="shop-header__right"><span :class="['store-status', s.shopStatus === 0 ? 'store-status--closed' : '']"><i/>{{ s.shopStatus === 1 ? '门店营业中' : '暂时休息中' }}</span><button class="avatar avatar--header" :aria-label="`账号：${s.userName}`" @click="showAccount = true">{{ s.userName ? s.userName.slice(0, 1) : '鲜' }}</button></div></header>
      <div class="shop-content"><section class="welcome-row"><div><span class="eyebrow">{{ harvestDay }} · DAILY HARVEST <span class="eyebrow-dot">✳</span> 每日清晨更新</span><h1>新鲜，<span>刚刚好。</span></h1><p>来自田间地头的好味道，今天刚好送到家。</p></div><button class="orders-shortcut" @click="showAccount = true"><span class="shortcut-icon"><PackageCheck :size="17"/></span><span><b>我的订单</b><small>看看鲜品到哪儿了</small></span><ChevronRight :size="16"/></button></section>
        <div v-if="s.error && s.mode === 'live'" class="connection-banner" role="status"><span class="connection-icon"><LoaderCircle :size="18"/></span><span><b>门店暂时无法连接</b><small>{{ s.error }}</small></span><button class="btn btn--soft btn--sm" @click="market.refreshShop">重试加载 <ArrowRight :size="14" /></button></div>
        <section id="sale" :class="['section', 'sale-section', { 'sale-section--focus': salePulse }]">
          <div class="section-heading"><div><div class="section-heading__eyebrow"><span>FRESH FINDS</span><i/><b>今天的特别</b></div><h2>好味道，不妨多一点。<span>限时特卖</span></h2></div><span class="sale-update"><i/>{{ openActivities.length ? `${openActivities.length} 场鲜享进行中` : '今日甄选 · 每日更新' }}</span></div>
          <div v-if="openActivities.length" class="sale-strip"><article v-for="(activity, index) in openActivities" :key="activity.id" class="sale-card" :class="`sale-card--${index % 3 + 1}`"><div class="sale-card__image"><img :src="activity.dishImage || activity.image" :alt="activity.dishName || activity.activityName" @error="imageError"><span class="sale-card__flag"><Clock3 :size="11"/> 限时鲜享</span><div class="sale-card__countdown">还剩 {{ activity.availableStock }} 份</div></div><div class="sale-card__info"><div><span>{{ activity.activityName }}</span><h3>{{ activity.dishName }}</h3><small>今日直采 · 鲜嫩正当时</small></div><button class="sale-card__cta" :aria-label="`参与 ${activity.activityName} 抢购`" @click="startPurchase(activity)"><span><small>抢购价</small><b>¥{{ money(activity.salePrice) }}</b><del>¥{{ money(activity.originalPrice) }}</del></span><span class="cta-circle"><ArrowRight :size="16"/></span></button></div></article></div>
          <div v-else class="sale-fallback" role="status"><span class="fallback-spark"><Star :size="18"/></span><span><b>下一场好物特卖，正在路上。</b><small>当前没有进行中的抢购活动，先看看今日在售好物吧。</small></span><button class="text-link" @click="scrollToSection('catalog')">浏览全部鲜品 <ArrowRight :size="14"/></button></div>
        </section>
        <section id="catalog" class="catalog-tools section"><div class="section-heading catalog-heading"><div><div class="section-heading__eyebrow"><span>FRESH MARKET</span><i/><b>按类别挑选，当日鲜配</b></div><h2>{{ search ? `找到 ${filteredProducts.length + filteredSetmeals.length} 份新鲜好物` : '想买什么，沿着分类慢慢挑。' }}</h2></div><span class="results-count">{{ filteredProducts.length + filteredSetmeals.length }} 款在售</span></div><div class="catalog-controls"><label class="catalog-search"><Search :size="15"/><input v-model="search" class="search-field__input" type="search" aria-label="搜索鲜品" placeholder="找找今天的鲜品"/><kbd>/</kbd></label><label class="sort-select"><span>优先推荐</span><select v-model="sort" aria-label="商品排序"><option value="featured">优先推荐</option><option value="price">价格由低到高</option><option value="price-desc">价格由高到低</option></select><ChevronDown :size="13"/></label></div></section>
        <div v-if="s.busy && !s.products.length && !s.setmeals.length" class="catalog-empty"><LoaderCircle :size="20" class="spin"/><span>正在为你挑选今日鲜品…</span></div>
        <template v-else>
          <section v-for="(category, categoryIndex) in visibleCategories" :id="categorySectionId(category)" :key="category.id" class="section catalog-category-section"><div class="section-heading catalog-category-heading"><div><div class="section-heading__eyebrow"><span>{{ String(categoryIndex + 1).padStart(2, '0') }} · FRESH PICKS</span><i/><b>今日鲜配</b></div><h2>{{ category.name }}</h2></div><span class="results-count">{{ productsForCategory(category.id).length }} 款</span></div><div class="product-grid"><article v-for="(product, index) in productsForCategory(category.id)" :key="product.id" class="product-card"><div class="product-card__photo"><img :src="product.image" :alt="product.name" :loading="index > 3 ? 'lazy' : 'eager'" @error="imageError"><span class="product-tag" :class="`product-tag--${index % 4}`">✳ &nbsp;{{ product.badge }}</span><button class="favorite-btn" :class="{ 'is-favorite': isFavorite(product.id) }" :aria-label="isFavorite(product.id) ? '取消收藏' : '收藏商品'" @click="market.favorite(product.id)"><Heart :size="16" :fill="isFavorite(product.id) ? 'currentColor' : 'none'"/></button><span v-if="index === 0" class="farm-stamp"><Leaf :size="11"/> 本地农场</span></div><div class="product-card__body"><span class="product-card__category">{{ placeLabel(product.categoryId) }} <i/> {{ product.unit }}</span><h3>{{ product.name }}</h3><p>{{ product.description || '今天清晨新鲜直采，天然生长的好味道。' }}</p><div class="product-card__foot"><div><strong><small>¥</small>{{ money(product.price) }}</strong><del>¥{{ money(product.originalPrice) }}</del></div><div v-if="count(product)" class="stepper"><button :aria-label="`减少${product.name}数量`" @click="minus(s.cart.find(p => p.dishId === product.id))"><Minus :size="13"/></button><span>{{ count(product) }}</span><button :aria-label="`增加${product.name}数量`" @click="add(product)"><Plus :size="13"/></button></div><button v-else class="add-btn" :aria-label="`加入购物袋：${product.name}`" @click="add(product)"><Plus :size="17"/><span>加入购物袋</span></button></div></div></article></div></section>
          <section v-if="filteredSetmeals.length" id="setmeals" class="section catalog-category-section"><div class="section-heading catalog-category-heading"><div><div class="section-heading__eyebrow"><span>FRESH SET · MEAL KITS</span><i/><b>鲜材组合</b></div><h2>把一餐所需的新鲜食材配齐。</h2></div><span class="results-count">{{ filteredSetmeals.length }} 款套餐</span></div><div class="product-grid"><article v-for="meal in filteredSetmeals" :key="meal.id" class="product-card"><div class="product-card__photo"><img :src="meal.image || '/fresh-harvest-hero.png'" :alt="meal.name" @error="imageError"><span class="product-tag product-tag--1">✳ &nbsp;鲜食搭配</span></div><div class="product-card__body"><span class="product-card__category">{{ s.setmealCategories.find(c => Number(c.id) === Number(meal.categoryId))?.name || '鲜食套餐' }} <i/> 生鲜食材组合</span><h3>{{ meal.name }}</h3><p>{{ meal.description || '把当季鲜味搭配好，省心带回家。' }}</p><button class="text-link" @click="openSetmeal(meal)">查看套餐组成 <ChevronRight :size="12"/></button><div class="product-card__foot"><div><strong><small>¥</small>{{ money(meal.price) }}</strong></div><div v-if="count({ ...meal, kind: 'setmeal' })" class="stepper"><button :aria-label="`减少${meal.name}数量`" @click="minus(s.cart.find(p => Number(p.setmealId) === Number(meal.id)))"><Minus :size="13"/></button><span>{{ count({ ...meal, kind: 'setmeal' }) }}</span><button :aria-label="`增加${meal.name}数量`" @click="add({ ...meal, kind: 'setmeal' })"><Plus :size="13"/></button></div><button v-else class="add-btn" :aria-label="`加入购物袋：${meal.name}`" @click="add({ ...meal, kind: 'setmeal' })"><Plus :size="17"/><span>加入购物袋</span></button></div></div></article></div></section>
          <div v-if="!filteredProducts.length && !filteredSetmeals.length && !s.busy" class="catalog-empty"><span>没有找到匹配的鲜品，换个关键词试试。</span><button class="text-link" @click="search = ''">清除搜索 <ArrowRight :size="14"/></button></div>
        </template>
        <section class="story-note"><div class="story-note__leaf"><Leaf :size="22"/></div><div><span class="eyebrow">A LITTLE NOTE FROM XIANJI</span><p>“新鲜不是路途的终点，而是每个用心的早晨。<br>今天刚好遇见好味道，就今天带回家。”</p></div><span class="story-signature">鲜集 · 一日一鲜 <i>↗</i></span></section><footer class="shop-footer"><span>鲜集 <i>·</i> 今日鲜活，日常欢喜。</span><span>每一份新鲜，都值得被认真对待 <Leaf :size="13"/></span></footer>
      </div><div v-if="totalItems" class="floating-bag"><button class="floating-bag__label" @click="showCart = true"><span class="bag-icon"><ShoppingBag :size="18"/><i>{{ totalItems }}</i></span><span>我的购物袋<small>{{ totalItems }} 份鲜品</small></span></button><span class="floating-bag__price"><small>合计</small><b>¥{{ money(market.total.value) }}</b></span><button class="btn btn--primary" @click="chooseCheckout">去结算 <ArrowRight :size="15"/></button></div></main>
  </div>
  <Transition><div v-if="s.toast" class="toast" role="status"><span class="toast__check"><Check :size="14" /></span>{{ s.toast }}<button aria-label="关闭提示" @click="s.toast = ''"><X :size="14"/></button></div></Transition>
  <Sheet :open="showCart" title="这一袋，都是好鲜味" size="medium" side @close="showCart = false"><div class="sheet-cart"><div v-if="s.cart.length" class="cart-lines"><article v-for="item in s.cart" :key="item.id" class="cart-line"><img :src="item.image" :alt="item.name" @error="imageError"><div class="cart-line__info"><small>{{ item.dishFlavor || '当日鲜选 · 新鲜现摘' }}</small><b>{{ item.name }}</b><span>¥{{ money(item.amount) }} × {{ item.number }}</span></div><div class="stepper stepper--cart"><button :aria-label="`减少${item.name}数量`" @click="minus(item)"><Minus :size="13"/></button><span>{{ quantity(item) }}</span><button :aria-label="`增加${item.name}数量`" @click="market.addCart(s.products.find(p => p.id === item.dishId) || item, item.dishFlavor)"><Plus :size="13"/></button></div></article></div><div v-else class="sheet-empty"><div class="sheet-empty__art"><ShoppingBag :size="27"/></div><h3>这一袋，还在等第一份新鲜。</h3><p>刚到的时令鲜品，每一份都刚刚好。</p><button class="btn btn--primary" @click="showCart = false; document.getElementById('catalog')?.scrollIntoView({ behavior: 'smooth' })">去挑选今日好物 <ArrowRight :size="15"/></button></div><div v-if="s.cart.length" class="cart-summary"><span>新鲜小计 <b>¥{{ money(market.total.value) }}</b></span><small><Truck :size="14"/> 同城冷链，约 30 分钟送达</small><button class="text-link cart-clear" @click="clearCart()">清空购物袋</button><button class="btn btn--primary btn--checkout" @click="chooseCheckout">继续结算 <span>¥{{ money(market.total.value) }}</span><ArrowRight :size="16"/></button></div></div></Sheet>
  <Sheet :open="showCheckout" title="确认这份新鲜" size="small" @close="showCheckout = false"><div class="checkout-body"><button class="delivery-card" @click="addressFormOpen(null)"><span class="delivery-card__icon"><MapPin :size="17" /></span><span><small>新鲜送至</small><b>{{ selectedAddress?.consignee || '选择收货地址' }} &nbsp; {{ selectedAddress?.phone || '' }}</b><span>{{ selectedAddress?.detail || '点击添加一处收货地址' }}</span></span><ChevronRight :size="17" /></button><div class="checkout-products"><article v-for="item in s.cart" :key="item.id"><img :src="item.image" :alt="item.name" @error="imageError"><span><b>{{ item.name }}</b><small>{{ item.dishFlavor || '鲜选' }} × {{ item.number }}</small></span><strong>¥{{ money(item.amount * item.number) }}</strong></article></div><label class="note-field">给这一单留句话 <input v-model="checkoutRemark" maxlength="80" placeholder="例如：请放在门口，谢谢"></label><div class="checkout-total"><span>商品金额 <b>¥{{ money(market.total.value) }}</b></span><span>新鲜配送 <b class="free-shipping">免费</b></span><div><span>实付合计</span><strong>¥{{ money(market.total.value) }}</strong></div></div><p class="checkout-policy"><ShieldCheck :size="15"/> {{ s.mode === 'demo' ? '这是本地演示订单，不会真实扣款。' : '下单后可在个人中心查看订单状态。' }}</p><button class="btn btn--primary btn--checkout" :disabled="processing" @click="placeOrder"><LoaderCircle v-if="processing" :size="16" class="spin"/><span v-else>下单并{{ s.mode === 'demo' ? '模拟付款' : '确认订单' }}</span><strong>¥{{ money(market.total.value) }}</strong></button></div></Sheet>
  <Sheet :open="showAddress" :title="addressForm.id?'编辑收货地址':'告诉我们，送到哪儿'" size="small" @close="showAddress = false"><form class="activity-form address-form" @submit.prevent="saveAddress"><label>收货人<input v-model="addressForm.consignee" required minlength="2" maxlength="24" placeholder="怎么称呼你" autocomplete="name"/></label><label>手机号码<input v-model="addressForm.phone" required pattern="1[3-9]\d{9}" maxlength="11" inputmode="numeric" placeholder="11 位手机号" autocomplete="tel"/></label><label>详细地址<input v-model="addressForm.detail" required minlength="5" maxlength="80" placeholder="小区、楼栋和房间号" autocomplete="street-address"/></label><label>地址标签<select v-model="addressForm.label"><option>家</option><option>公司</option><option>学校</option><option>其他</option></select></label><p class="form-tip"><MapPin :size="15"/> 本地配送范围由门店设置。</p><button class="btn btn--primary activity-submit" type="submit">{{ addressForm.id?'保存修改':'保存配送地址' }} <ArrowRight :size="16"/></button></form></Sheet>
  <Sheet :open="showActivityDetail" title="这份时令鲜享，刚刚好" size="small" @close="showActivityDetail = false"><div v-if="selectedActivity" class="activity-detail"><img :src="selectedActivity.dishImage || selectedActivity.image" :alt="selectedActivity.dishName || selectedActivity.activityName" @error="imageError"><span class="eyebrow">LIMITED HARVEST · 今日特卖</span><h3>{{ selectedActivity.dishName || selectedActivity.activityName }}</h3><p>清晨直采，当日新鲜送到。活动名额有限，售完即止。</p><div class="activity-detail__price"><strong>¥{{ money(selectedActivity.salePrice) }}</strong><del>原价 ¥{{ money(selectedActivity.originalPrice) }}</del><span>每人限购 {{ selectedActivity.limitPerUser }} 份</span></div><button class="delivery-card" @click="addressFormOpen(selectedActivity)"><MapPin :size="17"/><span><small>送到这儿</small><b>{{ selectedAddress?.consignee || s.addresses[0]?.consignee || '选择收货地址' }}</b><small>{{ selectedAddress?.detail || s.addresses[0]?.detail || '点击添加收货地址' }}</small></span><ChevronRight :size="17"/></button><button class="btn btn--primary activity-submit" :disabled="processing" @click="confirmPurchase"><LoaderCircle v-if="processing" :size="17" class="spin"/><span v-else>立即抢购 · ¥{{ money(selectedActivity.salePrice) }}</span><ArrowRight v-if="!processing" :size="16"/></button><button class="btn btn--soft activity-submit activity-cart-submit" :disabled="processing || addingActivityToCart" @click="addActivityToCart(selectedActivity)"><LoaderCircle v-if="addingActivityToCart" :size="16" class="spin"/><ShoppingBag v-else :size="16"/><span>{{ addingActivityToCart ? '正在加入购物袋…' : `加入购物袋 · 日常价 ¥${money(selectedActivity.originalPrice)}` }}</span></button></div></Sheet>
  <Sheet :open="showProductDetail" :title="selectedProduct?.name||'商品详情'" size="small" @close="showProductDetail = false"><div v-if="selectedProduct" class="activity-detail product-detail"><img :src="selectedProduct.image" :alt="selectedProduct.name" @error="imageError"/><span class="eyebrow">{{ placeLabel(selectedProduct.categoryId) }} · FRESH PICK</span><h3>{{ selectedProduct.name }}</h3><p>{{ selectedProduct.description||'今天清晨新鲜直采，天然生长的好味道。' }}</p><div v-for="flavor in selectedProduct.flavors||[]" :key="flavor.name" class="flavor-picker"><b>{{ flavor.name }}</b><div><button v-for="option in flavorOptions(flavor)" :key="option" :class="{active:selectedFlavors[flavor.name]===option}" @click="selectedFlavors[flavor.name]=option">{{ option }}</button></div></div><div class="activity-detail__price"><strong>¥{{ money(selectedProduct.price) }}</strong><span>{{ selectedProduct.unit||'今日鲜选' }}</span></div><button class="btn btn--primary activity-submit" @click="addSelectedFlavor"><Plus :size="16"/> 加入购物袋</button></div></Sheet>
  <Sheet :open="showSetmealDetail" title="这份套餐，搭配了什么" size="small" @close="showSetmealDetail = false"><div v-if="selectedSetmeal" class="setmeal-detail"><img :src="selectedSetmeal.image||'/fresh-harvest-hero.png'" :alt="selectedSetmeal.name" @error="imageError"/><span class="eyebrow">SEASONAL SET · 鲜食搭配</span><h3>{{ selectedSetmeal.name }}</h3><p>{{ selectedSetmeal.description||'把当季鲜味搭配好，省心带回家。' }}</p><div class="setmeal-ingredients"><article v-for="dish in selectedSetmeal.setmealDishes||[]" :key="dish.dishId||dish.name"><span>{{ dish.name }}</span><small>{{ dish.copies||1 }} 份 · ¥{{ money(dish.price) }}</small></article><p v-if="!selectedSetmeal.setmealDishes?.length">套餐明细暂不可用，请稍后重试。</p></div><div class="activity-detail__price"><strong>¥{{ money(selectedSetmeal.price) }}</strong><span>组合价 · 一键加入购物袋</span></div><button class="btn btn--primary activity-submit" @click="add({...selectedSetmeal,kind:'setmeal'});showSetmealDetail=false"><Plus :size="16"/> 加入购物袋</button></div></Sheet>
  <Sheet :open="showAccount" title="我的鲜集小日子" size="medium" side @close="showAccount = false"><div class="account-body"><div class="account-profile"><span class="account-profile__avatar">{{ s.userName ? s.userName.slice(0, 1) : '鲜' }}</span><div><span class="eyebrow">FRESH MEMBER · 会员中心</span><h3>{{ s.userName || '今天好，鲜集的朋友。' }}</h3><small>已安全连接您的鲜集账户。</small></div></div><section class="account-orders"><div class="panel-heading"><h2>最近一单 <span>{{ s.orders.length }} 单</span></h2><button class="text-link" @click="market.refreshUser()">更新 <ArrowRight :size="13"/></button></div><nav class="account-order-filters"><button :class="{active:orderFilter==='all'}" @click="orderFilter='all'">全部</button><button v-for="(label,status) in orderLabels" :key="status" :class="{active:orderFilter===String(status)}" @click="orderFilter=String(status)">{{ label }}</button></nav><article v-for="order in latestOrders" :key="order.id" class="account-order"><div class="account-order__status"><span class="status-pip"/><b>{{ orderLabels[order.status] || '已接单' }}</b><small>{{ String(order.orderTime || '刚刚').replace('T', ' ').slice(0, 16) }}</small></div><div class="account-order__info"><span>{{ order.orderDishes || (order.orderDetailList || []).map(d => `${d.name} × ${d.number}`).join('、') || '一份新鲜好物' }}</span><b>¥{{ money(order.amount) }}</b><button class="text-link" @click="openOrder(order)">{{ order.status === 1 ? '尽快付款' : order.status === 4 ? '确认收到' : order.status === 5 ? '再来一单' : '查看订单' }} <ChevronRight :size="12"/></button></div></article><div v-if="!latestOrders.length" class="account-empty"><span class="account-empty__flower">✳</span><b>还没有鲜品订单。</b><small>今天刚好遇见好味道，现在就开始。</small><button class="btn btn--soft btn--sm" @click="showAccount = false; document.getElementById('catalog')?.scrollIntoView({ behavior: 'smooth' })">去挑选今日鲜选 <ArrowRight :size="13"/></button></div></section><section class="account-addresses"><div class="panel-heading"><h2>收货地址 <span>{{ s.addresses.length }} 处</span></h2><button class="text-link"  @click="addressFormOpen(null,null,true)"><Plus :size="13"/> 新增地址</button></div><article v-for="address in s.addresses" :key="address.id" class="account-address"><div><b>{{ address.consignee }} · {{ address.phone }}</b><small>{{ address.detail }}</small></div><span v-if="address.isDefault===1" class="status-chip status-chip--open">默认</span><button v-else class="text-link" @click="setDefaultAddress(address)">设为默认</button><button class="text-link" @click="editAddress(address)">编辑</button><button class="text-link text-link--danger" @click="removeAddress(address)">删除</button></article><div v-if="!s.addresses.length" class="account-empty account-empty--compact"><small>添加收货地址，结算时就能快速选择。</small></div></section><div v-if="activeOrder" class="order-detail-card"><div><span class="status-pip"/>订单 {{ activeOrder.number || activeOrder.orderNumber || `#${activeOrder.id}` }} <b>¥{{ money(activeOrder.amount) }}</b></div><small>{{ activeOrder.consignee||addressName }} · {{ activeOrder.phone||'' }} · {{ activeOrder.address||activeOrder.addressBook?.detail||'同城冷链配送' }}</small><div v-if="activeOrder.orderDetailList?.length" class="account-order-detail"><span v-for="item in activeOrder.orderDetailList" :key="item.id||item.name">{{ item.name }} × {{ item.number }} <b>¥{{ money(item.amount*item.number) }}</b></span></div><small v-if="activeOrder.remark">订单备注：{{ activeOrder.remark }}</small><div v-if="[1,2,3,4,5,6].includes(activeOrder.status)" class="order-detail-card__actions"><button v-if="activeOrder.status === 1" class="btn btn--primary btn--sm" @click="payOrder(activeOrder)"><CreditCard :size="14"/> 微信支付（模拟）</button><button v-if="activeOrder.status === 4" class="btn btn--primary btn--sm" @click="orderAction(activeOrder, 'complete')"><Check :size="14"/> 确认收货</button><button v-if="[1,2,3].includes(activeOrder.status)" class="btn btn--soft btn--sm" @click="orderAction(activeOrder, 'cancel')">取消订单</button><button v-if="[2,3,4].includes(activeOrder.status)" class="btn btn--soft btn--sm" @click="orderAction(activeOrder, 'reminder')"><Bell :size="14"/> 催单</button><button v-if="[5,6].includes(activeOrder.status)" class="btn btn--soft btn--sm" @click="repeatOrder(activeOrder)"><RotateCw :size="14"/> 再来一单</button></div></div><button class="btn btn--soft activity-submit account-login" @click="signedOutCustomer">退出当前账户</button></div></Sheet>
</template>
